import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`nutritionist-audit`,heroTitle:`Audit your nutrition practice's website in minutes`,heroSubtitle:`Perplexity Computer reviews your nutrition practice website, credentials, service offers, booking path, and visibility, then creates a prioritized plan to convert more prospects.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yournutritionpractice.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this nutrition practice. 1) Review the website for service clarity, credentials, specialty positioning, pricing or package clarity, mobile UX, and booking friction. 2) Audit local and telehealth visibility, trust signals, testimonials, and compliance-sensitive claims. 3) Compare against relevant nutritionists and wellness practices for offer structure, lead magnets, and appointment CTAs. 4) Recommend the highest-impact fixes for consultation bookings, program inquiries, and qualified leads. 5) Deliver a prioritized action plan with rewritten copy, booking-flow improvements, and growth recommendations.`,heroOverlaySteps:[`Reviewing your nutrition practice site, credentials, services, and booking path`,`Benchmarking relevant practices on offers, trust signals, and visibility`,`Finding the copy, credibility, and UX gaps holding back qualified leads`,`Booking fixes, positioning updates, and growth priorities ready to use`],generatingSteps:[`Visiting {url} to inspect your nutrition practice website and conversion path`,`Designing an agent to compare relevant practices, visibility, and trust signals`,`Configuring service copy rewrites, credibility improvements, and booking fixes`,`Setting up a prioritized action plan for more qualified consultations`],featureSectionTitle:`From health interest to qualified consultations`,featureCardTitles:[`Connects to your practice stack`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your nutrition practice audit into site review, offer positioning, visibility analysis, and competitor research, then routes each step to the right model.`,`Booking pages, Google Business Profile, Docs, Sheets, and planning tools can all feed one workflow so recommendations stay actionable.`,`Service rewrites. Lead magnet ideas. Booking-flow improvements. Trust and visibility priorities. Computer gives you updates tied to more qualified leads.`],capabilitySectionTitle:`Your nutrition practice growth team, on autopilot`,capabilitySectionSubtitle:`Paste your nutrition practice URL, step away, and come back to a clearer plan to grow consultations.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review service pages, specialty positioning, credentials, package clarity, booking flow, and mobile UX.`},{title:`Visibility Review`,description:`Computer can assess local and telehealth visibility, testimonials, trust signals, and search positioning against relevant practices.`},{title:`Offer Positioning`,description:`Computer can rewrite service copy, package framing, and CTA language so prospects understand the next step.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across booking tools, Google Business Profile, Docs, and Sheets so your team can execute quickly.`},{title:`Remember Your Specialty`,description:`Computer can remember your services, client focus, program offers, and tone so future audits start with the right context.`},{title:`Monitor Lead Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix most likely to improve consultation volume.`}]});export{t as default};
